import { EventEmitter } from "node:events";
import { web } from "@easyplane/proto";
import { protoToUuid } from "@easyplane/shared";

import type { RpcSession } from "../rpc/session.js";
import { RemoteWebClient } from "./remote-client.js";

export interface HeartbeatSnapshot {
  receivedAt: number;
  machineId: string;
  /** Per-connection session id generated by the client. */
  instId: string;
  userToken: string;
  easytierVersion: string;
  hostname: string;
  reportTime: string;
  runningNetworkInstances: string[];
  deviceOs: web.DeviceOsInfo;
  supportConfigSource: boolean;
}

export interface ManagedClientEvents {
  heartbeat: [snapshot: HeartbeatSnapshot];
  closed: [];
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => {
    const timer = setTimeout(resolve, ms);
    timer.unref?.();
  });
}

/** One connected easytier-core config-server client. */
export class ManagedClient extends EventEmitter<ManagedClientEvents> {
  readonly remote: RemoteWebClient;
  readonly connectedAt = Date.now();
  private readonly heartbeats: HeartbeatSnapshot[] = [];
  private closed = false;
  private closeReason: string | undefined;
  private heartbeatWaiters: Array<{ count: number; resolve: () => void }> = [];
  private closeWaiters: Array<() => void> = [];

  constructor(readonly session: RpcSession) {
    super();
    this.remote = new RemoteWebClient(session);
    session.on("closed", () => {
      this.closed = true;
      for (const waiter of this.closeWaiters.splice(0)) waiter();
      this.emit("closed");
    });
  }

  get id(): string {
    return this.session.id;
  }

  get transportKind(): RpcSession["transportKind"] {
    return this.session.transportKind;
  }

  get secure(): boolean {
    return this.session.secure;
  }

  get label(): string {
    return this.session.label;
  }

  get remoteAddress(): string {
    return this.session.remoteAddress;
  }

  get heartbeatCount(): number {
    return this.heartbeats.length;
  }

  /** Wall-clock timestamp of the newest heartbeat, or null before the first. */
  get lastHeartbeatAt(): number | null {
    return this.heartbeats.at(-1)?.receivedAt ?? null;
  }

  get latestHeartbeat(): HeartbeatSnapshot | undefined {
    return this.heartbeats[this.heartbeats.length - 1];
  }

  get heartbeatHistory(): readonly HeartbeatSnapshot[] {
    return this.heartbeats;
  }

  get isClosed(): boolean {
    return this.closed;
  }

  get error(): Error | undefined {
    return this.session.lastError;
  }

  recordHeartbeat(request: web.HeartbeatRequest): HeartbeatSnapshot {
    const machineId = request.machineId ? protoToUuid(request.machineId) : "";
    const instId = request.instId ? protoToUuid(request.instId) : "";
    const snapshot: HeartbeatSnapshot = {
      receivedAt: Date.now(),
      machineId,
      instId,
      userToken: request.userToken,
      easytierVersion: request.easytierVersion,
      hostname: request.hostname,
      reportTime: request.reportTime,
      runningNetworkInstances: request.runningNetworkInstances.map(protoToUuid),
      deviceOs: request.deviceOs ?? { osType: "", version: "", distribution: "" },
      supportConfigSource: request.supportConfigSource,
    };
    this.heartbeats.push(snapshot);
    if (this.heartbeats.length > 256) this.heartbeats.shift();
    for (const waiter of this.heartbeatWaiters) {
      if (this.heartbeats.length >= waiter.count) {
        waiter.resolve();
      }
    }
    this.heartbeatWaiters = this.heartbeatWaiters.filter(
      (waiter) => this.heartbeats.length < waiter.count,
    );
    this.emit("heartbeat", snapshot);
    return snapshot;
  }

  /** Wait until at least `count` heartbeats have been observed. */
  async waitForHeartbeats(count: number, timeoutMs = 15_000): Promise<void> {
    if (this.heartbeats.length >= count) return;
    const deadline = Date.now() + timeoutMs;
    await new Promise<void>((resolve, reject) => {
      const waiter = { count, resolve };
      this.heartbeatWaiters.push(waiter);
      void (async () => {
        while (Date.now() < deadline) {
          if (this.heartbeats.length >= count) {
            resolve();
            return;
          }
          if (this.closed) {
            reject(new Error(`client closed while waiting for ${count} heartbeats`));
            return;
          }
          await sleep(100);
        }
        const index = this.heartbeatWaiters.indexOf(waiter);
        if (index >= 0) this.heartbeatWaiters.splice(index, 1);
        reject(new Error(`timed out waiting for ${count} heartbeats (got ${this.heartbeats.length})`));
      })();
    });
  }

  async waitForClose(timeoutMs = 10_000): Promise<void> {
    if (this.closed) return;
    await new Promise<void>((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error("timed out waiting for client disconnect"));
      }, timeoutMs);
      timer.unref?.();
      this.closeWaiters.push(() => {
        clearTimeout(timer);
        resolve();
      });
    });
  }

  close(reason = "closed by server"): void {
    this.closeReason = reason;
    this.session.close(reason);
  }

  get closedReason(): string | undefined {
    return this.closeReason;
  }
}
